erhouden tot de keuze die anderen mede voor haar bepaalden. Hun hernieuwde ontmoetingen draaien om spijt, maatschappelijke verwachtingen en de mogelijkheid om op een later moment alsnog een eigen beslissing te nemen.","work_id":977100038,"evidence":[{"url":"https://metadata.isbn.nl/2059552/overreding-en-overtuiging.html","fact":"Paperback ISBN 9789403866314 verschijningsdatum 28/05/2026 NUR 301 Literaire roman, novelle imprint Nordisk Menorah Press uitgever Mijnbestseller B.V. taal Nederlands","sha256":"c7012767093e8533cf1e91867516e612f4d5eefafc4aa8e157de302760c53603","checkedAt":"2026-11-01T14:02:31.079Z","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge.","sourceAuthors":"Jane Austen"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/2059552/overreding-en-overtuiging.html","reviewed_at":"2026-11-01T14:24:00+00:00","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl006-reviewed-batch-04-20261101","review_status":"approved","bound_author_id":977300001},"before_row":null},{"key":{"id":977200123},"seq":28,"relation":"editions","after_row":{"id":977200123,"title":"Verstand en gevoel","isbn_10":null,"isbn_13":"9789076542874","work_id":977100039,"cover_id":null,"language":"nld","publisher":"Kemper Conseil Publishing Consultancy","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":977200123},"seq":29,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":977100039,"evidence":[{"url":"https://metadata.isbn.nl/864594/verstand-en-gevoel.html","fact":"Paperback ISBN 9789076542874 verschijningsdatum 06/02/2018 NUR 350 Fictie overig algemeen 300 Literaire fictie algemeen 301 Literaire roman, novelle 310 Pockets algemeen 311 Pockets literaire fictie 302 Vertaalde literaire roman, novelle 315 Vertaalde pockets imprint Kemper Conseil Publi