zeeman Edmond Dantès wordt door mensen die hij vertrouwt vals van landverraad beschuldigd. Zijn gevangenschap maakt een einde aan zijn toekomstplannen en voedt een verlangen naar vergelding. Een medegevangene vertelt hem over een verborgen schat. Wanneer ontsnapping mogelijk wordt, ziet Dantès daarin een middel om terug te keren naar de wereld die hem heeft verraden en zijn vroegere vijanden met hun daden te confronteren.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/114796/de-graaf-van-montecristo.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/114796/de-graaf-van-montecristo.html","sha256":"fa0f45c4cdb11227ace7f559563ced0f504fc5c519168598f4b12ebdc67f8f1c","checkedAt":"2026-11-01T14:00:49.542Z","fact":"Paperback ISBN 9789020413021 verschijningsdatum 19/12/2012 NUR 302 Vertaalde literaire roman, novelle uitgever Atlas Contact, Uitgeverij taal Nederlands","sourceAuthors":"Alexandre Dumas","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789029543118","key":{"id":977200115},"before":null,"after":{"work_id":977100031,"title":"De getalenteerde Mr. Ripley","language":"nld","isbn_13":"9789029543118","isbn_10":null,"open_library_edition_id":null,"publisher":"Singel Uitgeverijen","id":977200115}},{"relation":"catalog_edition_metadata","ref":"metadata:9789029543118","key":{"edition_id":"@edition:9789029543118"},"before":null,"after":{"edition_id":"@edition:9789029543118","work_id":977100031,"bound_author_id":977300014,"bound_title":"De getalenteerde Mr. Ripley","bound_language":"nld","bound_isbn13":"9789029543118","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000530474_De_getalenteerde_Mr._Ripley